import { ExternalLink, GitBranch } from "lucide-react"; import { Project } from "@/data/projects";
export function ProjectCard({project}:{project:Project}){return <article className="project"><div className="thumb" data-category={project.category}/><div className="project-body"><div style={{display:"flex",justifyContent:"space-between",gap:8}}><h3>{project.title}</h3><span className="tiny">{project.date}</span></div><p>{project.description}</p><div className="chipset">{project.tags.slice(0,4).map(x=><span className="tag" key={x}>{x}</span>)}</div></div><div className="links"><a target="_blank" rel="noreferrer" href={project.live}>Live <ExternalLink size={12}/></a><a target="_blank" rel="noreferrer" href={project.github}>GitHub <GitBranch size={12}/></a></div></article>}
